import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")
    if not isinstance(destination_directory, str) or not destination_directory:
        raise ValueError("Invalid destination directory provided.")

    if not os.path.exists(destination_directory):
        os.makedirs(destination_directory)

    try:
        response = requests.get(url, headers=headers, stream=True, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download the zip file: {e}") from e

