import requests
import json
import pandas as pd
import seaborn as sns
# Constants
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    if not parameters or not isinstance(parameters, dict):
        raise Exception("Invalid parameters provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("Empty data received from the API.")
        df = pd.DataFrame(data)
        if df.empty or df.select_dtypes(include=[float, int]).empty:
            raise Exception("Invalid or non-numerical data for correlation analysis.")
        correlation_matrix = df.select_dtypes(include=[float, int]).corr()
        ax = sns.heatmap(correlation_matrix, annot=True, cmap="coolwarm")
        return df, ax
    except Exception as e:
        raise Exception(f"Error processing the request or data: {e}")

